import{_ as t,a0 as o,w as r,s as f,ao as l,I as i,x as s,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"使用 OfflineIMAP 同步邮件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 OfflineIMAP 同步邮件 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 OfflineIMAP 同步邮件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 OfflineIMAP 同步邮件 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20200113 Keep your email in sync with OfflineIMAP","title":"使用 OfflineIMAP 同步邮件","tag":"202001","desc":""},"relativePath":"202001/20200113 Keep your email in sync with OfflineIMAP.md","filePath":"[post].md"}'),u={name:"202001/20200113 Keep your email in sync with OfflineIMAP.md"};function m(d,n,M,P,A,g){const a=o("Link");return r(),f("div",null,[n[20]||(n[20]=l('<h1 id="使用-offlineimap-同步邮件" tabindex="-1">使用 OfflineIMAP 同步邮件 <a class="header-anchor" href="#使用-offlineimap-同步邮件" aria-label="Permalink to “使用 OfflineIMAP 同步邮件”">​</a></h1><blockquote><p>将邮件镜像保存到本地是整理消息的第一步。在我们的 20 个使用开源提升生产力的系列的第三篇文章中了解该如何做。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202001/20/235324nbgfyuwl98syowta.jpg" alt=""></p><p>去年，我在 19 天里给你介绍了 19 个新（对你而言）的生产力工具。今年，我换了一种方式：使用你在使用或者还没使用的工具，构建一个使你可以在新一年更加高效的环境。</p><h3 id="使用-offlineimap-在本地同步你的邮件" tabindex="-1">使用 OfflineIMAP 在本地同步你的邮件 <a class="header-anchor" href="#使用-offlineimap-在本地同步你的邮件" aria-label="Permalink to “使用 OfflineIMAP 在本地同步你的邮件”">​</a></h3><p>我与邮件之间存在爱恨交织的关系。我喜欢它让我与世界各地的人交流的方式。但是，像你们中的许多人一样，我收到过很多邮件，许多是来自邮件列表的，但也有很多垃圾邮件、广告等。这些积累了很多。</p><p><img src="https://opensource.com/sites/default/files/uploads/productivity_3-1.png" alt="The OfflineIMAP &quot;blinkenlights&quot; UI" title="The OfflineIMAP &quot;blinkenlights&quot; UI"></p>',7)),i("p",null,[n[2]||(n[2]=s("我尝试过的大多数工具（除了大型邮件服务商外）都可以很好地处理大量邮件，它们都有一个共同点：它们都依赖于以 ",-1)),e(a,{href:"https://en.wikipedia.org/wiki/Maildir"},{default:p(()=>[...n[0]||(n[0]=[s("Maildir",-1)])]),_:1}),n[3]||(n[3]=s(" 格式存储的本地邮件副本。这其中最有用的是 ",-1)),e(a,{href:"http://www.offlineimap.org/"},{default:p(()=>[...n[1]||(n[1]=[s("OfflineIMAP",-1)])]),_:1}),n[4]||(n[4]=s("。OfflineIMAP 是将 IMAP 邮箱镜像到本地 Maildir 文件夹树的 Python 脚本。我用它来创建邮件的本地副本并使其保持同步。大多数 Linux 发行版都包含它，并且可以通过 Python 的 pip 包管理器获得。",-1))]),n[21]||(n[21]=l(`<p>示例的最小配置文件是一个很好的模板。首先将其复制到 <code>~/.offlineimaprc</code>。我的看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[general]</span></span>
<span class="line"><span>accounts = LocalSync</span></span>
<span class="line"><span>ui=Quiet</span></span>
<span class="line"><span>autorefresh=30</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Account LocalSync]</span></span>
<span class="line"><span>localrepository = LocalMail</span></span>
<span class="line"><span>remoterepository = MirrorIMAP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Repository MirrorIMAP]</span></span>
<span class="line"><span>type = IMAP</span></span>
<span class="line"><span>remotehost = my.mail.server</span></span>
<span class="line"><span>remoteuser = myusername</span></span>
<span class="line"><span>remotepass = mypassword</span></span>
<span class="line"><span>auth_mechanisms = LOGIN</span></span>
<span class="line"><span>createfolder = true</span></span>
<span class="line"><span>ssl = yes</span></span>
<span class="line"><span>sslcacertfile = OS-DEFAULT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Repository LocalMail]</span></span>
<span class="line"><span>type = Maildir</span></span>
<span class="line"><span>localfolders = ~/Maildir</span></span>
<span class="line"><span>sep = .</span></span>
<span class="line"><span>createfolder = true</span></span></code></pre></div><p>我的配置要做的是定义两个仓库：远程 IMAP 服务器和本地 Maildir 文件夹。还有一个<strong>帐户</strong>，告诉 OfflineIMAP 运行时要同步什么。你可以定义链接到不同仓库的多个帐户。除了本地复制外，这还允许你从一台 IMAP 服务器复制到另一台作为备份。</p><p>如果你有很多邮件，那么首次运行 OfflineIMAP 将花费一些时间。但是完成后，下次会花<em>少得多</em>的时间。你也可以将 OfflineIMAP 作为 cron 任务（我的偏好）或作为守护程序在仓库之间不断进行同步。其文档涵盖了所有这些内容以及 Gmail 等高级配置选项。</p><p>现在，我的邮件已在本地复制，并有多种工具用来加快搜索、归档和管理邮件的速度。这些我明天再说。</p><hr>`,6)),i("p",null,[n[6]||(n[6]=s("via: ",-1)),e(a,{href:"https://opensource.com/article/20/1/sync-email-offlineimap"},{default:p(()=>[...n[5]||(n[5]=[s("https://opensource.com/article/20/1/sync-email-offlineimap",-1)])]),_:1})]),i("p",null,[n[11]||(n[11]=s("作者：",-1)),e(a,{href:"https://opensource.com/users/ksonney"},{default:p(()=>[...n[7]||(n[7]=[s("Kevin Sonney",-1)])]),_:1}),n[12]||(n[12]=s(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:p(()=>[...n[8]||(n[8]=[s("lujun9972",-1)])]),_:1}),n[13]||(n[13]=s(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:p(()=>[...n[9]||(n[9]=[s("geekpi",-1)])]),_:1}),n[14]||(n[14]=s(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:p(()=>[...n[10]||(n[10]=[s("wxy",-1)])]),_:1})]),i("p",null,[n[17]||(n[17]=s("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[15]||(n[15]=[s("LCTT",-1)])]),_:1}),n[18]||(n[18]=s(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:p(()=>[...n[16]||(n[16]=[s("Linux中国",-1)])]),_:1}),n[19]||(n[19]=s(" 荣誉推出",-1))])])}const h=t(u,[["render",m]]);export{T as __pageData,h as default};
